-- Vihaar Industries initial schema. Apply to a fresh Supabase project using the SQL editor or Supabase CLI.
create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','business','owner','admin','finance','operations','content_manager');
create type public.order_status as enum ('draft','pending_payment','confirmed','processing','packed','shipped','delivered','cancelled','refunded');
create type public.journal_status as enum ('draft','posted','reversed');
create type public.account_type as enum ('asset','liability','equity','revenue','expense');
create table public.profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 email text, full_name text, phone text, role public.app_role not null default 'customer',
 business_legal_name text, gstin text, fssai_number text, country_code char(2) default 'IN',
 business_verified_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.addresses (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, label text, recipient_name text not null, phone text, line1 text not null, line2 text, city text not null, state_region text, postal_code text, country_code char(2) not null, is_default boolean not null default false, created_at timestamptz not null default now());
create table public.product_categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, sort_order int not null default 0, is_visible boolean not null default true, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), category_id uuid references public.product_categories(id), name text not null, slug text not null unique, sku text unique, short_description text, description text, ingredients text, specifications jsonb not null default '{}', retail_price_minor bigint check(retail_price_minor>=0), wholesale_price_minor bigint check(wholesale_price_minor>=0), currency char(3) not null default 'INR', tax_code text, tax_rate numeric(6,3) not null default 0 check(tax_rate between 0 and 100), unit text not null default 'kg', min_order_quantity numeric(14,3) not null default 1, is_active boolean not null default false, is_featured boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_media (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, storage_path text not null, alt_text text, sort_order int not null default 0, is_primary boolean not null default false, created_at timestamptz not null default now());
create table public.site_sections (id uuid primary key default gen_random_uuid(), section_key text not null unique, title text not null, content jsonb not null default '{}', is_visible boolean not null default true, sort_order int not null default 0, updated_at timestamptz not null default now());
create table public.certificates (id uuid primary key default gen_random_uuid(), title text not null, certificate_type text not null, certificate_number text, issuer text, valid_from date, valid_until date, storage_path text, is_public boolean not null default false, created_at timestamptz not null default now());
create table public.testimonials (id uuid primary key default gen_random_uuid(), customer_name text not null, company_name text, quote text not null, rating int check(rating between 1 and 5), approved boolean not null default false, is_visible boolean not null default false, created_at timestamptz not null default now());
create table public.enquiries (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete set null, name text not null, email text not null, company text, enquiry_type text not null, product_id uuid references public.products(id) on delete set null, details text not null, quantity_text text, destination_country text, status text not null default 'new' check(status in ('new','in_progress','quoted','won','lost','closed')), assigned_to uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), order_number text not null unique, user_id uuid not null references public.profiles(id), order_type text not null check(order_type in ('retail','business','export')), status public.order_status not null default 'pending_payment', currency char(3) not null default 'INR', subtotal_minor bigint not null default 0 check(subtotal_minor>=0), discount_minor bigint not null default 0 check(discount_minor>=0), tax_minor bigint not null default 0 check(tax_minor>=0), shipping_minor bigint not null default 0 check(shipping_minor>=0), total_minor bigint not null default 0 check(total_minor>=0), coupon_id uuid, shipping_address jsonb not null default '{}', billing_address jsonb not null default '{}', payment_provider text, payment_reference text, courier_provider text, courier_reference text, tracking_url text, placed_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name_snapshot text not null, sku_snapshot text, quantity numeric(14,3) not null check(quantity>0), unit_price_minor bigint not null check(unit_price_minor>=0), tax_rate numeric(6,3) not null default 0, tax_minor bigint not null default 0, line_total_minor bigint not null check(line_total_minor>=0));
create table public.inventory_locations (id uuid primary key default gen_random_uuid(), name text not null, location_code text unique, is_active boolean not null default true);
create table public.inventory_batches (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), location_id uuid references public.inventory_locations(id), batch_number text not null, manufactured_on date, expires_on date, quantity_on_hand numeric(14,3) not null default 0 check(quantity_on_hand>=0), quantity_reserved numeric(14,3) not null default 0 check(quantity_reserved>=0), unit_cost_minor bigint check(unit_cost_minor>=0), supplier_name text, created_at timestamptz not null default now(), unique(product_id,batch_number));
create table public.stock_movements (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id), batch_id uuid references public.inventory_batches(id), order_id uuid references public.orders(id), movement_type text not null check(movement_type in ('receipt','sale','return','adjustment','waste','transfer','reservation','release')), quantity_delta numeric(14,3) not null, unit_cost_minor bigint, reference text, notes text, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.promotions (id uuid primary key default gen_random_uuid(), code text not null unique, promotion_type text not null check(promotion_type in ('coupon','referral')), discount_type text not null check(discount_type in ('percentage','fixed')), discount_value numeric(14,3) not null check(discount_value>0), max_discount_minor bigint, minimum_order_minor bigint not null default 0, starts_at timestamptz, expires_at timestamptz, total_uses_limit int, per_user_limit int not null default 1, uses_count int not null default 0, applies_to text not null default 'all' check(applies_to in ('retail','business','all')), is_active boolean not null default false, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.referrals (id uuid primary key default gen_random_uuid(), referrer_user_id uuid not null references public.profiles(id), referred_user_id uuid references public.profiles(id), referral_code text not null unique, reward_minor bigint not null default 0, reward_currency char(3) not null default 'INR', status text not null default 'pending' check(status in ('pending','qualified','rewarded','rejected')), qualified_order_id uuid references public.orders(id), created_at timestamptz not null default now(), unique(referrer_user_id,referred_user_id));
create table public.promotion_redemptions (id uuid primary key default gen_random_uuid(), promotion_id uuid not null references public.promotions(id), user_id uuid not null references public.profiles(id), order_id uuid not null references public.orders(id), discount_minor bigint not null check(discount_minor>=0), created_at timestamptz not null default now(), unique(promotion_id,order_id));
create table public.chart_of_accounts (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, account_type public.account_type not null, parent_id uuid references public.chart_of_accounts(id), currency char(3) not null default 'INR', is_control_account boolean not null default false, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.journal_entries (id uuid primary key default gen_random_uuid(), entry_number bigint generated always as identity unique, entry_date date not null default current_date, description text not null, source_type text, source_id uuid, status public.journal_status not null default 'draft', currency char(3) not null default 'INR', created_by uuid references public.profiles(id), posted_by uuid references public.profiles(id), posted_at timestamptz, reversal_of uuid references public.journal_entries(id), created_at timestamptz not null default now());
create table public.journal_lines (id uuid primary key default gen_random_uuid(), journal_entry_id uuid not null references public.journal_entries(id) on delete restrict, account_id uuid not null references public.chart_of_accounts(id), description text, debit_minor bigint not null default 0 check(debit_minor>=0), credit_minor bigint not null default 0 check(credit_minor>=0), customer_id uuid references public.profiles(id), supplier_name text, tax_code text, created_at timestamptz not null default now(), check(not (debit_minor>0 and credit_minor>0))); 
create table public.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id), amount_minor bigint not null check(amount_minor>0), currency char(3) not null default 'INR', payment_method text, provider text, provider_reference text, status text not null check(status in ('pending','authorised','captured','failed','refunded','partially_refunded')), received_at timestamptz, created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id text, before_data jsonb, after_data jsonb, ip_hash text, created_at timestamptz not null default now());
create index orders_user_created_idx on public.orders(user_id,created_at desc); create index orders_status_idx on public.orders(status); create index products_active_idx on public.products(is_active); create index enquiries_status_idx on public.enquiries(status,created_at desc); create index stock_product_idx on public.inventory_batches(product_id); create index journal_entry_date_idx on public.journal_entries(entry_date,status); create index audit_entity_idx on public.audit_logs(entity_type,entity_id,created_at desc);
-- User profile is created automatically; role is always customer by default. Never allow users to self-assign privileged roles.
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name,role) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',''), 'customer') on conflict(id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
